The QueryResult shim reaches into an internal file (resolve(...).replace(/index\.js$/, 'query_result.js')) and patches its prototype. This is tightly coupled to @ladybugdb/wasm-core’s published file layout and can break on patch/minor updates even if the public API stays compatible. A more robust approach is to wrap the QueryResult instances returned from query/execute (or wrap Connection.query/execute) and provide getAll() there, without relying on internal module paths.
```suggestion
  // Native getAll() returns objects keyed by column name, so we adapt the
  // results of query()/execute() to expose getAll() without touching any
  // internal @ladybugdb/wasm-core modules or prototypes.
  const wrapQueryResult = (result: any): any => {
    if (!result) return result;

    const patch = (qr: any) => {
      if (qr && !qr.getAll && typeof qr.getAllObjects === 'function') {
        qr.getAll = qr.getAllObjects.bind(qr);
      }
      return qr;
    };

    return Array.isArray(result) ? result.map(patch) : patch(result);
  };

  const OrigConnection = mod.Connection;
  const WasmConnectionShim = function (this: any, ...args: any[]) {
    return new OrigConnection(...args);
  } as unknown as typeof OrigConnection;
  WasmConnectionShim.prototype = Object.create(OrigConnection.prototype);
  WasmConnectionShim.prototype.constructor = WasmConnectionShim;

  WasmConnectionShim.prototype.query = async function (...args: any[]) {
    const result = await OrigConnection.prototype.query.apply(this, args);
    return wrapQueryResult(result);
  };

  WasmConnectionShim.prototype.execute = async function (...args: any[]) {
    const result = await OrigConnection.prototype.execute.apply(this, args);
    return wrapQueryResult(result);
  };

  mod.Connection = WasmConnectionShim;
```

