```ts
export async function withHandleLock<T>(lock: { lockTail: Promise<void> }, fn: () => Promise<T>): Promise<T> {
  const prior = lock.lockTail;
  let release!: () => void;
  lock.lockTail = new Promise<void>((resolve) => { release = resolve; });
  await prior;
  try { return await fn(); } finally { release(); }
}

